import json
import sys

# Operation tags (internal)
GET, PUT, DEL, CAS, SCAN = range(5)


def solve(request):
    txs = request.get('transactions') or []
    initial = request.get('initial') or {}
    final = request.get('final') or {}
    n = len(txs)

    if n == 0:
        return {"order": [] if initial == final else None}

    # Universe of keys that can ever be present in the map.
    keyset = set(initial) | set(final)
    for t in txs:
        for op in t['ops']:
            if op[0] != 'scan':
                keyset.add(op[1])
    keys = sorted(keyset)
    K = len(keys)
    kidx = {k: i for i, k in enumerate(keys)}

    # Compile operations to work on a value tuple aligned with `keys`.
    # None represents an absent key.
    compiled = []
    for t in txs:
        c = []
        for op in t['ops']:
            tag = op[0]
            if tag == 'get':
                c.append((GET, kidx[op[1]], op[2]))
            elif tag == 'put':
                c.append((PUT, kidx[op[1]], op[2]))
            elif tag == 'del':
                c.append((DEL, kidx[op[1]]))
            elif tag == 'cas':
                c.append((CAS, kidx[op[1]], op[2], op[3], op[4]))
            else:  # scan
                lo, hi, exp = op[1], op[2], op[3]
                idxs = tuple(j for j, k in enumerate(keys) if lo <= k < hi)
                c.append((SCAN, idxs, exp))
        compiled.append(c)

    init_state = tuple(initial.get(k) for k in keys)
    final_state = tuple(final.get(k) for k in keys)

    starts = [t['start'] for t in txs]
    ends = [t['end'] for t in txs]

    # Real-time precedence: j must precede i iff end[j] <= start[i].
    pre = [0] * n
    for i in range(n):
        m = 0
        si = starts[i]
        for j in range(n):
            if j != i and ends[j] <= si:
                m |= 1 << j
        pre[i] = m

    # Keys each transaction may write (over-approximation for CAS).
    key_writers = [0] * K
    for i, c in enumerate(compiled):
        for op in c:
            if op[0] == PUT or op[0] == DEL or op[0] == CAS:
                key_writers[op[1]] |= 1 << i

    full = (1 << n) - 1
    # Try candidates in time order: usually finds a witness quickly.
    cand = sorted(range(n), key=lambda i: (starts[i], ends[i], i))

    memo = set()  # failed (placed_mask, state) entries

    def simulate(c, state):
        vals = list(state)
        for op in c:
            tag = op[0]
            if tag == GET:
                if vals[op[1]] != op[2]:
                    return None
            elif tag == PUT:
                vals[op[1]] = op[2]
            elif tag == DEL:
                vals[op[1]] = None
            elif tag == CAS:
                ok = vals[op[1]] == op[2]
                if ok != op[4]:
                    return None
                if ok:
                    vals[op[1]] = op[3]  # op[3] is None -> delete
            else:  # SCAN
                got = [[keys[j], vals[j]] for j in op[1] if vals[j] is not None]
                if got != op[2]:
                    return None
        return tuple(vals)

    def dfs(placed, state):
        if placed == full:
            return () if state == final_state else None
        entry = (placed, state)
        if entry in memo:
            return None
        remaining = full ^ placed
        # Prune: a key differing from its final value that no remaining
        # transaction can ever write makes completion impossible.
        for j in range(K):
            if state[j] != final_state[j] and not (key_writers[j] & remaining):
                memo.add(entry)
                return None
        for i in cand:
            b = 1 << i
            if (placed & b) or (pre[i] & remaining):
                continue
            ns = simulate(compiled[i], state)
            if ns is None:
                continue
            r = dfs(placed | b, ns)
            if r is not None:
                return (i,) + r
        memo.add(entry)
        return None

    path = dfs(0, init_state)
    if path is None:
        return {"order": None}
    return {"order": [txs[i]['id'] for i in path]}


def main():
    out = []
    for line in sys.stdin:
        line = line.strip()
        if not line:
            continue
        try:
            out.append(json.dumps(solve(json.loads(line))))
        except Exception as exc:  # defensive: never crash the batch
            print('error: %r' % (exc,), file=sys.stderr)
            out.append(json.dumps({"order": None}))
    sys.stdout.write('\n'.join(out) + ('\n' if out else ''))


if __name__ == '__main__':
    main()
