import json, random, sys, itertools, time
sys.path.insert(0, '/app')
from public_contract import valid_history
from main import solve

def brute_force(request):
    txs = request['transactions']
    n = len(txs)
    for perm in itertools.permutations(range(n)):
        order = [txs[i]['id'] for i in perm]
        ok = True
        ranks = {x: r for r, x in enumerate(order)}
        for a in txs:
            for b in txs:
                if a['end'] <= b['start'] and ranks[a['id']] >= ranks[b['id']]:
                    ok = False; break
            if not ok: break
        if not ok: continue
        if valid_history(request, order):
            return order
    return None

KEYS = ['a', 'b', 'c', 'd', 'e', 'f', 'aa', 'zz']
BOUNDS = ['', 'a', 'b', 'c', 'd', 'e', 'f', 'g', 'm', 'z', 'zz', 'zzz']

def rand_key(pool):
    return random.choice(pool)

def rand_val():
    return random.randint(-9, 9)

def rand_op(pool, allkeys):
    r = random.random()
    if r < 0.25:
        k = rand_key(pool)
        exp = random.choice([None, rand_val(), rand_val()])
        return ['get', k, exp]
    elif r < 0.45:
        return ['put', rand_key(pool), rand_val()]
    elif r < 0.55:
        return ['del', rand_key(pool)]
    elif r < 0.75:
        k = rand_key(pool)
        old = random.choice([None, rand_val()])
        new = random.choice([None, rand_val()])
        want = random.choice([True, False])
        return ['cas', k, old, new, want]
    else:
        a = random.choice(BOUNDS[1:])
        b = random.choice(BOUNDS[1:])
        if a >= b: a, b = b, a
        if a == b: b = b + 'x'
        # expected pairs: random subset of keys in range with random values
        pairs = []
        for k in sorted(allkeys):
            if a <= k < b and random.random() < 0.5:
                pairs.append([k, rand_val()])
        return ['scan', a, b, pairs]

def rand_request(maxn=7, sat_bias=0.5):
    nkeys = random.randint(1, 6)
    pool = random.sample(KEYS, nkeys)
    allkeys = set(pool)
    n = random.randint(0, maxn)
    txs = []
    for i in range(n):
        s = random.randint(0, 12)
        e = s + random.randint(1, 8)
        ops = [rand_op(pool, allkeys) for _ in range(random.randint(1, 5))]
        txs.append({'id': 't%d' % i, 'start': s, 'end': e, 'ops': ops})
    initial = {k: rand_val() for k in pool if random.random() < 0.4}
    req = {'initial': initial, 'final': {}, 'transactions': txs}
    if random.random() < sat_bias and n > 0:
        # Build a satisfiable instance: pick a random valid order, simulate
        # while fixing observations to actual results.
        order = list(range(n))
        random.shuffle(order)
        # repair to respect precedence: simple bubble
        def rank_ok(o):
            ranks = {x: r for r, x in enumerate(o)}
            return all(not (txs[a]['end'] <= txs[b]['start'] and ranks[txs[a]['id']] >= ranks[txs[b]['id']])
                       for a in range(n) for b in range(n))
        tries = 0
        while not rank_ok(order) and tries < 100:
            random.shuffle(order); tries += 1
        d = dict(initial)
        for i in order:
            for op in txs[i]['ops']:
                if op[0] == 'get':
                    op[2] = d.get(op[1])
                elif op[0] == 'put':
                    d[op[1]] = op[2]
                elif op[0] == 'del':
                    d.pop(op[1], None)
                elif op[0] == 'cas':
                    ok = d.get(op[1]) == op[2]
                    op[4] = ok
                    if ok:
                        if op[3] is None: d.pop(op[1], None)
                        else: d[op[1]] = op[3]
                else:
                    op[3] = sorted([[k, v] for k, v in d.items() if op[1] <= k < op[2]])
        req['final'] = d
        # sometimes corrupt one observation to make it (likely) unsat
        if random.random() < 0.35:
            t = random.choice(txs)
            op = random.choice(t['ops'])
            if op[0] == 'get':
                op[2] = rand_val() if op[2] is None else (None if random.random() < 0.3 else (op[2] + random.choice([1, -1, 2])) % 10)
            elif op[0] == 'cas':
                op[4] = not op[4]
            elif op[0] == 'scan':
                op[3] = op[3] + [['q' , 1]] if random.random() < 0.5 else op[3][:-1]
    else:
        req['final'] = {k: rand_val() for k in pool if random.random() < 0.4}
    return req

def main():
    random.seed(int(sys.argv[1]) if len(sys.argv) > 1 else 42)
    iters = int(sys.argv[2]) if len(sys.argv) > 2 else 2000
    t0 = time.time()
    nsat = nunsat = 0
    for it in range(iters):
        req = rand_request()
        exp = brute_force(req)
        got = solve(req)
        if exp is None:
            if got['order'] is not None:
                print('MISMATCH: expected None, got', got, '\n', json.dumps(req)); return 1
            nunsat += 1
        else:
            if got['order'] is None or not valid_history(req, got['order']):
                print('MISMATCH: expected sat, got', got, '\n', json.dumps(req), '\nbrute:', exp); return 1
            nsat += 1
    print('OK %d iters (sat=%d unsat=%d) in %.2fs' % (iters, nsat, nunsat, time.time() - t0))
    return 0

if __name__ == '__main__':
    sys.exit(main())
