import json, random, sys, time
sys.path.insert(0, '/app')
from public_contract import valid_history
from main import solve

def timed(name, req, expect=None):
    t0 = time.time()
    got = solve(req)
    dt = time.time() - t0
    status = ''
    if got['order'] is not None:
        ok = valid_history(req, got['order'])
        status = 'sat(valid=%s)' % ok
        assert ok
    else:
        status = 'unsat'
    if expect == 'sat': assert got['order'] is not None, name
    if expect == 'unsat': assert got['order'] is None, name
    print('%-28s %6.2fs  %s' % (name, dt, status))
    return dt

# 1. 10 fully-overlapping txs, reads force unique order t0..t9
txs = []
for i in range(10):
    ops = ([['get', 'a', i - 1]] if i > 0 else [['get', 'a', None]]) + [['put', 'a', i]]
    txs.append({'id': 't%d' % i, 'start': 0, 'end': 10, 'ops': ops})
timed('forced-chain-10', {'initial': {}, 'final': {'a': 9}, 'transactions': txs}, 'sat')

# 2. same, but unsat: final demands a=0 (t0 last contradicts reads)
timed('forced-chain-10-unsat', {'initial': {}, 'final': {'a': 0}, 'transactions': txs}, 'unsat')

# 3. adversarial unsat: tx i writes 5 of 6 keys with unique value i-9;
#    final demands key j to hold value of tx j (which skips key j)
keys = ['a', 'b', 'c', 'd', 'e', 'f']
txs = []
for i in range(10):
    ops = [['put', keys[j], i - 9] for j in range(6) if j != i % 6]
    txs.append({'id': 't%d' % i, 'start': 0, 'end': 100, 'ops': ops})
final = {keys[j]: j - 9 for j in range(6)}
timed('lastwriter-unsat', {'initial': {}, 'final': final, 'transactions': txs}, 'unsat')

# 4. like 3 but final value writable by someone; last-writer cycle unsat:
#    key a wants v0 (written by t0..all), construct cycle via distinct values:
#    tx i writes key i and key (i+1)%6 with value vi; final wants key i = v(i+1)%6
txs = []
for i in range(6):
    ops = [['put', keys[i], i], ['put', keys[(i + 1) % 6], i],
           ['get', keys[(i + 2) % 6], None]]
    txs.append({'id': 't%d' % i, 'start': 0, 'end': 100, 'ops': ops})
txs += [{'id': 't%d' % i, 'start': 0, 'end': 100, 'ops': [['get', keys[i % 6], None]]} for i in range(6, 10)]
final = {keys[i]: (i + 1) % 6 for i in range(6)}
timed('writer-cycle-unsat', {'initial': {}, 'final': final, 'transactions': txs})

# 5. satisfiable heavy: 10 txs, each 5 ops mixed, fully overlapping
random.seed(5)
def big_case(seed, corrupt):
    random.seed(seed)
    ks = ['a', 'b', 'c', 'd', 'e', 'f']
    txs = []
    for i in range(10):
        ops = []
        for _ in range(5):
            r = random.random()
            if r < 0.35: ops.append(['put', random.choice(ks), random.randint(-9, 9)])
            elif r < 0.5: ops.append(['del', random.choice(ks)])
            elif r < 0.7: ops.append(['cas', random.choice(ks), random.randint(-9, 9), random.randint(-9, 9), True])
            elif r < 0.85: ops.append(['get', random.choice(ks), None])
            else: ops.append(['scan', 'a', 'z', []])
        txs.append({'id': 't%d' % i, 'start': 0, 'end': 100, 'ops': ops})
    # simulate t0..t9 and fix observations to actual values
    d = {}
    for t in txs:
        for op in t['ops']:
            if op[0] == 'get': op[2] = d.get(op[1])
            elif op[0] == 'put': d[op[1]] = op[2]
            elif op[0] == 'del': d.pop(op[1], None)
            elif op[0] == 'cas':
                ok = d.get(op[1]) == op[2]
                op[4] = ok
                if ok:
                    if op[3] is None: d.pop(op[1], None)
                    else: d[op[1]] = op[3]
            else: op[3] = sorted([[k, v] for k, v in d.items() if op[1] <= k < op[2]])
    req = {'initial': {}, 'final': dict(d), 'transactions': txs}
    if corrupt:
        # corrupt the last tx's final-affecting op so final is off by one
        req['final'] = dict(d)
        k = random.choice(ks)
        req['final'][k] = (d.get(k, 0) + 1) % 10 - 9
    return req

for s in range(6):
    timed('big-sat-%d' % s, big_case(s, False), 'sat')
for s in range(6, 12):
    timed('big-corrupt-%d' % s, big_case(s, True))

# 6. dense gets: every tx reads all keys expecting specific values (unsat search)
random.seed(77)
ks = ['a', 'b', 'c', 'd', 'e', 'f']
txs = []
for i in range(10):
    ops = [['get', k, random.randint(-9, 9)] for k in ks[:4]]
    ops.append(['put', random.choice(ks), random.randint(-9, 9)])
    txs.append({'id': 't%d' % i, 'start': 0, 'end': 100, 'ops': ops})
timed('dense-gets', {'initial': {k: 0 for k in ks}, 'final': {k: 0 for k in ks}, 'transactions': txs})

# 7. timing chains with precedence DAG (partial order)
txs = []
for i in range(10):
    txs.append({'id': 't%d' % i, 'start': i, 'end': i + 5,
                'ops': [['get', 'x', i - 1] if i else ['get', 'x', None], ['put', 'x', i]]})
timed('precedence-dag', {'initial': {}, 'final': {'x': 9}, 'transactions': txs}, 'sat')
