    ends = [t['end'] for t in txs]

    # Per (tx, key): cert = value the tx certainly leaves (UNKNOWN if it may
    # depend on the incoming state), poss = set of values it may leave for
    # some incoming state.
    cert = [[UNKNOWN] * K for _ in range(n)]
    poss = [None] * n
