    # Derived precedence: in any witness the last effective writer of key j
    # must be able to leave final[j]. If exactly one tx w can, every tx that
    # certainly leaves a different value must precede w.
    prod = [dict() for _ in range(K)]  # key -> {value: bitmask}
    impossible = False
    for j in range(K):
        pm = prod[j]
        for i in range(n):
            for v in poss[i][j]:
                pm[v] = pm.get(v, 0) | (1 << i)
