            # rewrites the key, or the persisted initial value is wrong too.
            if init_state[j] != fj or any(cert[i][j] is not UNKNOWN for i in S):
                impossible = True
                break
            continue
        if len(P) == 1:
            w = P[0]
            for u in S:
                if u != w and cert[u][j] is not UNKNOWN and cert[u][j] != fj:
                    pre[w] |= 1 << u

    if not impossible:
        # Transitive closure of precedence; a cycle means no witness.
        for i in range(n):
            m = pre[i]
            while True:
                add = 0
                mm = m
                while mm:
                    b = mm & (-mm)
                    add |= pre[b.bit_length() - 1]
                    mm ^= b
                add &= ~m
                if not add:
                    break
                m |= add
            pre[i] = m
            if (m >> i) & 1:
                impossible = True
                break
