        return {"order": None}

    full = (1 << n) - 1
    # Try candidates in time order: usually finds a witness quickly.
    cand = sorted(range(n), key=lambda i: (starts[i], ends[i], i))

    memo = set()  # failed (placed_mask, state) entries

    def simulate(c, state):
        vals = list(state)
        for op in c:
            tag = op[0]
            if tag == GET:
                if vals[op[1]] != op[2]:
                    return None
            elif tag == PUT:
                vals[op[1]] = op[2]
            elif tag == DEL:
                vals[op[1]] = None
            elif tag == CAS:
                ok = vals[op[1]] == op[2]
                if ok != op[4]:
                    return None
                if ok:
                    vals[op[1]] = op[3]  # op[3] is None -> delete
            else:  # SCAN
                got = [[keys[j], vals[j]] for j in op[1] if vals[j] is not None]
