            if ns is None:
                continue
            r = dfs(placed | b, ns)
            if r is not None:
                return (i,) + r
        memo.add(entry)
        return None

    path = dfs(0, init_state)
    if path is None:
        return {"order": None}
    return {"order": [txs[i]['id'] for i in path]}


